// AccountingServiceServer is the server API for AccountingService service.
// All implementations must embed UnimplementedAccountingServiceServer
// for forward compatibility.
type AccountingServiceServer interface {
	// Auth (no token required)
	Register(context.Context, *RegisterRequest) (*AuthResponse, error)
	Login(context.Context, *LoginRequest) (*AuthResponse, error)
	RequestRecovery(context.Context, *RequestRecoveryRequest) (*Empty, error)
	ValidateRecoveryToken(context.Context, *RecoveryTokenRequest) (*RecoveryTokenResponse, error)
	RecoverAccount(context.Context, *RecoverAccountRequest) (*AuthResponse, error)
	BeginPasskeyLogin(context.Context, *BeginPasskeyLoginRequest) (*PasskeyOptionsResponse, error)
	FinishPasskeyLogin(context.Context, *FinishPasskeyRequest) (*AuthResponse, error)
	// Account
	Me(context.Context, *Empty) (*User, error)
	ChangePassword(context.Context, *ChangePasswordRequest) (*Empty, error)
	BeginPasskeyRegistration(context.Context, *Empty) (*PasskeyOptionsResponse, error)
	FinishPasskeyRegistration(context.Context, *FinishPasskeyRequest) (*Passkey, error)
	ListPasskeys(context.Context, *Empty) (*ListPasskeysResponse, error)
	DeletePasskey(context.Context, *IdRequest) (*Empty, error)
	// Companies
	CreateCompany(context.Context, *Company) (*Company, error)
	UpdateCompany(context.Context, *Company) (*Company, error)
	ListCompanies(context.Context, *Empty) (*ListCompaniesResponse, error)
	GetCompany(context.Context, *CompanyRequest) (*Company, error)
	// Projects
	CreateProject(context.Context, *Project) (*Project, error)
	UpdateProject(context.Context, *Project) (*Project, error)
	DeleteProject(context.Context, *CompanyIdRequest) (*Empty, error)
	ListProjects(context.Context, *ListProjectsRequest) (*ListProjectsResponse, error)
	GetProject(context.Context, *CompanyIdRequest) (*Project, error)
	// Categories
	ListCategories(context.Context, *CompanyRequest) (*ListCategoriesResponse, error)
	CreateCategory(context.Context, *Category) (*Category, error)
	UpdateCategory(context.Context, *Category) (*Category, error)
	DeleteCategory(context.Context, *CompanyIdRequest) (*Empty, error)
	// Invoices
	CreateInvoice(context.Context, *Invoice) (*Invoice, error)
	UpdateInvoice(context.Context, *Invoice) (*Invoice, error)
	ListInvoices(context.Context, *ListInvoicesRequest) (*ListInvoicesResponse, error)
	GetInvoice(context.Context, *CompanyIdRequest) (*Invoice, error)
	IssueInvoice(context.Context, *CompanyIdRequest) (*Invoice, error)
	SendInvoice(context.Context, *CompanyIdRequest) (*Invoice, error)
	GetInvoicePdf(context.Context, *CompanyIdRequest) (*FileResponse, error)
	MarkInvoicePaid(context.Context, *MarkInvoicePaidRequest) (*Invoice, error)
	UnlinkInvoicePayment(context.Context, *CompanyIdRequest) (*Invoice, error)
	CancelInvoice(context.Context, *CompanyIdRequest) (*Invoice, error)
	DeleteInvoice(context.Context, *CompanyIdRequest) (*Empty, error)
	// Banking
	ListBankProviders(context.Context, *Empty) (*ListBankProvidersResponse, error)
	ListInstitutions(context.Context, *ListInstitutionsRequest) (*ListInstitutionsResponse, error)
	CreateBankConnection(context.Context, *CreateBankConnectionRequest) (*CreateBankConnectionResponse, error)
	CompleteBankConnection(context.Context, *CompleteBankConnectionRequest) (*BankConnection, error)
	UpdateBankConnection(context.Context, *UpdateBankConnectionRequest) (*BankConnection, error)
	ReconnectBankConnection(context.Context, *CompanyIdRequest) (*CreateBankConnectionResponse, error)
	ListBankConnections(context.Context, *CompanyRequest) (*ListBankConnectionsResponse, error)
	DeleteBankConnection(context.Context, *CompanyIdRequest) (*Empty, error)
	ListBankAccounts(context.Context, *CompanyRequest) (*ListBankAccountsResponse, error)
	SetPrimaryAccount(context.Context, *CompanyIdRequest) (*Empty, error)
	SyncNow(context.Context, *CompanyRequest) (*SyncNowResponse, error)
	GetBalanceHistory(context.Context, *BalanceHistoryRequest) (*BalanceHistoryResponse, error)
	UploadStatement(context.Context, *UploadStatementRequest) (*UploadStatementResponse, error)
	// Transactions
	ListTransactions(context.Context, *ListTransactionsRequest) (*ListTransactionsResponse, error)
	ExplainTransaction(context.Context, *ExplainTransactionRequest) (*Transaction, error)
	ApproveTransactions(context.Context, *ApproveTransactionsRequest) (*Empty, error)
	LinkTransactionToInvoice(context.Context, *LinkTransactionRequest) (*Transaction, error)
	UploadAttachment(context.Context, *UploadAttachmentRequest) (*Attachment, error)
	ListAttachments(context.Context, *ListAttachmentsRequest) (*ListAttachmentsResponse, error)
	GetAttachment(context.Context, *CompanyIdRequest) (*FileResponse, error)
	DeleteAttachment(context.Context, *CompanyIdRequest) (*Empty, error)
	// Dashboard
	GetOverview(context.Context, *OverviewRequest) (*OverviewResponse, error)
	mustEmbedUnimplementedAccountingServiceServer()
}

